-- Service only (0001_rls.sql default-deny): make it explicit in case default privileges differ.
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON "push_tokens", "push_log" FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON "push_tokens", "push_log" FROM authenticated;
  END IF;
END $$;
